def ensure_task(
        self, task_input: EmailClassificationTaskInput
    ) -> EmailClassificationTask:
        input_json = json.dumps(
            task_input.payload(),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
        task_id = (
            "email-classification:"
            + sha256(task_input.stable_message_identity.encode("utf-8")).hexdigest()
        )
        with self.email_store._connect() as db:
            db.execute("begin immediate")
            row = db.execute(
                "select * from email_agent_classification_tasks where stable_message_identity=?",
                (task_input.stable_message_identity,),
            ).fetchone()
            if row is None:
                db.execute(
                    """
                    insert into email_agent_classification_tasks (
                        task_id, channel, stable_message_identity, status, input_json
                    ) values (?, 'email', ?, 'pending', ?)
                    """,
                    (task_id, task_input.stable_message_identity, input_json),
                )
                row = db.execute(
                    "select * from email_agent_classification_tasks where task_id=?",
                    (task_id,),
                ).fetchone()
            elif row["input_json"] != input_json:
                existing_payload = json.loads(row["input_json"])
                candidate_payload = json.loads(input_json)
                if not isinstance(existing_payload, dict):
                    raise ValueError("stable classification task input is invalid")
                if existing_payload.get("input_compacted") is True:
                    same_input = existing_payload.get("identity_sha256") == self._identity_sha256(candidate_payload)
                else:
                    existing_payload.pop("scheduled_consumer", None)
                    candidate_payload.pop("scheduled_consumer", None)
                    same_input = existing_payload == candidate_payload
                if not same_input:
                    raise ValueError("stable classification task input changed")
        assert row is not None
        return self._row(row)

